Rules.InvariantScript:
// Screen-specific data — scoped here, not globally
ClearCollect(col_HazardTypes,
    {Value:"Flooding"}, {Value:"Fallen Tree"}, {Value:"Storm Damage"},
    {Value:"Road Hazard"}, {Value:"Fire"}, {Value:"Structural Damage"}
);

// Only used as fallback if SharePoint not yet connected
ClearCollect(col_RecentReports,
    {HazardType:"Flooding",     Location:"Parramatta Road, Sydney",    Reporter:"Community Member", Severity:"high",   TimeAgo:"10 mins ago"},
    {HazardType:"Fallen Tree",  Location:"Pacific Highway, Newcastle", Reporter:"Community Member", Severity:"medium", TimeAgo:"25 mins ago"},
    {HazardType:"Storm Damage", Location:"George Street, Wollongong",  Reporter:"Local Resident",   Severity:"high",   TimeAgo:"1 hour ago"},
    {HazardType:"Road Hazard",  Location:"King Street, Penrith",       Reporter:"Community Member", Severity:"low",    TimeAgo:"2 hours ago"}
);

Set(currentUserID, Blank());

Navigate(LoginScreen);

Notify(
    "You have been logged out.",
    NotificationType.Information
);

ForAll(
    Users,
    Patch(
        AssignedUsers,
        Defaults(AssignedUsers),
        {
            UserId: ID,
            EmergencyId: Form2_1.LastSubmit.ID,
            AUStatus: {Value: "Pending"}
        }
    )
);

Refresh(AssignedUsers);

// Save the selected required skills
ForAll(
    requiredSkills As s,
    Patch(
        EmergencySkills,
        Defaults(EmergencySkills),
        {
            EmergencyId: Form2_1.LastSubmit.ID,
            QualificationId:
                LookUp(
                    Qualifications,
                    Title = s.Title
                ).ID
        }
    )
);

// After patching → update context
UpdateContext(
    {
        CurrentItem: Form2_1.LastSubmit,
        isItemSelected: false
    }
);

// User feedback
Notify(
    "Success",
    NotificationType.Success
);

// Reset form
ResetForm(Form2_1);

// After patching → update context
UpdateContext(
    {
        CurrentItem: Form2_1.LastSubmit,
        isItemSelected: false
    }
);

// User feedback
Notify(
    "Success",
    NotificationType.Success
);


// Reset form
ResetForm(Form2_1);

Set(
    requiredSkills,
    RequiredSkills.SelectedItems
);


// Set status before submitting
Set(defaultStatus, { Value: "Active" });

// Submit form
SubmitForm(Form2_1);

Patch(
    Emergencies,
    Form2_1.LastSubmit,
    {
        Status: { Value: "Active" }
    }
);

Refresh(Emergencies);
